d0/validate.py:
"""Strict D.0 schema + cross-field validators. No process execution, signing or approvals.

Requires jsonschema>=4.20. Does not trust JSON Schema alone for cross-field rules.
"""
from __future__ import annotations
import hashlib
import json
from datetime import datetime
from pathlib import Path
from jsonschema import Draft202012Validator
from referencing import Registry, Resource

SCHEMA_DIR = Path(__file__).parent / 'schemas'
SCHEMAS = {p.name.removesuffix('.schema.json'): json.loads(p.read_text(encoding='utf8'))
           for p in SCHEMA_DIR.glob('*.schema.json')}
REGISTRY = Registry().with_resources([(s['$id'], Resource.from_contents(s)) for s in SCHEMAS.values()])

class ContractError(ValueError):
    pass

def canonical_json_bytes(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False,
                      allow_nan=False).encode('utf8')

def digest(value):
    return hashlib.sha256(canonical_json_bytes(value)).hexdigest()

def validate(name, value):
    if name not in SCHEMAS:
        raise ContractError(f'Unknown schema: {name}')
    errors = sorted(Draft202012Validator(SCHEMAS[name], registry=REGISTRY).iter_errors(value),
                    key=lambda e: str(list(e.path)))
    if errors:
        e = errors[0]
        raise ContractError(f'{name} at {list(e.path)}: {e.message}')
    if name == 'ember-output-v1':
        import math
        if not all(math.isfinite(x) for x in value['features']):
            raise ContractError('EMBER feature vector must contain only finite numbers')
    if name == 'target_ref':
        if value['kind'] == 'FILE' and not isinstance(value['observed'].get('path'), str):
            raise ContractError('FILE requires observed.path')
        if value['kind'] == 'PROCESS' and (not isinstance(value['observed'].get('pid'), int)
                                         or isinstance(value['observed'].get('pid'), bool)):
            raise ContractError('PROCESS requires observed.pid')
    if name == 'observation':
        if value['status'] == 'SUCCESS' and value['coverage'] == 'NONE':
            raise ContractError('SUCCESS cannot have NONE coverage')
        if value['status'] != 'SUCCESS' and value['value'] is not None:
            raise ContractError('Non-SUCCESS value must be null (retain partial data as artifact)')
        if value['content_origin'] != 'trusted_system' and value['trust_level'] != 'UNTRUSTED_CONTENT':
            raise ContractError('Target/provider content cannot be marked trusted')
    if name == 'tool_result':
        for ob in value['observations']:
            validate('observation', ob)
        if value['status'] != 'SUCCESS' and value['error'] is None and value['status'] not in ('PARTIAL',):
            raise ContractError('Failed/cancelled/denied result needs error')
    if name == 'execution_receipt':
        if value['outcome'] == 'SUCCESS' and value['target_binding']['status'] != 'VERIFIED':
            raise ContractError('Success requires VERIFIED target binding')
        if value['cleanup']['status'] == 'COMPLETE' and value['cleanup']['remaining_owned_resources']:
            raise ContractError('COMPLETE cleanup cannot have remaining resources')
        if datetime.fromisoformat(value['finished_at'].replace('Z','+00:00')) < datetime.fromisoformat(value['started_at'].replace('Z','+00:00')):
            raise ContractError('finish before start')
    if name == 'approval_request':
        if datetime.fromisoformat(value['expires_at'].replace('Z','+00:00')) <= datetime.fromisoformat(value['requested_at'].replace('Z','+00:00')):
            raise ContractError('Approval expires before request')
    return value

def verify_tool_call(spec, call, case, *, provider_available=True):
    """Pre-dispatch checks, not a substitute for locked transactional admission."""
    validate('tool_spec', spec); validate('tool_call', call)
    if not spec['enabled'] or not provider_available:
        raise ContractError('Tool/provider unavailable; never silently fallback')
    if (call['tool_id'], call['tool_version'], call['provider_id']) != (spec['tool_id'], spec['tool_version'], spec['provider']['id']):
        raise ContractError('Tool/provider binding mismatch')
    if call['target_ref']['kind'] not in spec['supported_targets']:
        raise ContractError('Unsupported target kind')
    if call['case_id'] != case['case_id'] or call['expected_revision'] != case['revision']:
        raise ContractError('Stale case revision or wrong case')
    if call['budget']['timeout_ms'] > spec['limits']['timeout_ms'] or call['budget']['max_output_bytes'] > spec['limits']['max_output_bytes']:
        raise ContractError('Requested budget exceeds tool limits')
    # bc_contracts is in project root when patch installed; do not reimplement identity rules.
    try:
        from bc_contracts import same_target_ref
    except ImportError as exc:
        raise ContractError('Node B/C v1.2 bc_contracts.py required') from exc
    if not same_target_ref(case['target_ref'], call['target_ref']):
        raise ContractError('TargetRef mismatch')
    if call['target_ref']['identity_strength'] == 'UNAVAILABLE':
        raise ContractError('Unverified identity cannot be dispatched')
    return True

def verify_receipt_result(receipt, result, call):
    validate('execution_receipt', receipt); validate('tool_result', result); validate('tool_call', call)
    for key in ('run_id','call_id','case_id','tool_id','tool_version'):
        if receipt[key] != result[key]:
            raise ContractError(f'{key} mismatch')
    if result['call_id'] != call['call_id'] or result['case_id'] != call['case_id']:
        raise ContractError('Result/call mismatch')
    if receipt['provider'] != result['provider'] or receipt['provider']['id'] != call['provider_id']:
        raise ContractError('Provider swapped')
    if receipt['arguments_sha256'] != digest(call['arguments']):
        raise ContractError('Arguments tampered')
    if result['receipt_sha256'] != digest(receipt):
        raise ContractError('Receipt hash mismatch')
    if result['status'] != receipt['outcome']:
        raise ContractError('Outcome mismatch')
    if result['target_ref'] != call['target_ref']:
        raise ContractError('Result target differs from requested target')
    if receipt['target_binding']['observed_ref'] != call['target_ref']:
        raise ContractError('Receipt target differs from requested target')
    if receipt['resources']['output_bytes'] > call['budget']['max_output_bytes']:
        raise ContractError('Output exceeds call budget')
    if receipt['target_binding']['status'] != 'VERIFIED' and result['status'] == 'SUCCESS':
        raise ContractError('Unverified target')
    return True

evaluation/task05c/evidence_projection.p:
"""Evidence projection for FEATURE_RECORD_REPLAY.

Turns an official EMBER2018 v2 feature *record* into a small set of provenance-
tagged, static-only evidence observations the agent may reason over. Hard rules:

  * Only metadata/feature groups that actually exist in the record are projected.
  * No raw 2381-float vector is exposed.
  * No runtime / network / process-behaviour observation is fabricated.
  * `has_signature` means a signature STRUCTURE is present, NOT that it is valid
    or trusted (no cryptographic verification is performed); labelled as such.
  * Each observation carries a deterministic evidence_id and FEATURE_RECORD_REPLAY
    provenance, so hallucinated / cross-case evidence IDs are detectable.

Ground truth label is NEVER part of a projection.
"""
from __future__ import annotations

import hashlib
from typing import Any, Dict, List, Mapping

DATASET = "EMBER2018 feature version 2 (feature records)"
TRACK = "FEATURE_RECORD_REPLAY"

MAX_SECTIONS = 40
MAX_LIBRARIES = 30
MAX_IMPORT_FUNCS = 60


def evidence_id(record_sha: str, facet: str) -> str:
    return "EV-" + hashlib.sha256(f"{record_sha}:{facet}".encode()).hexdigest()[:24]


def _obs(record_sha: str, facet: str, value: Any, limitations=None) -> Dict[str, Any]:
    return {
        "evidence_id": evidence_id(record_sha, facet),
        "facet": facet,
        "status": "SUCCESS",
        "value": value,
        "trust_level": "UNTRUSTED_CONTENT",
        "content_origin": "provider_output",
        "limitations": limitations or [],
        "provenance": {"track": TRACK, "record_sha256": record_sha, "dataset": DATASET},
        "artifact_ref": None,
    }


def project_record(record: Mapping[str, Any]) -> Dict[str, Any]:
    """Return {target_sha256, observations[]} derived ONLY from present fields."""
    sha = record.get("sha256") or ""
    obs: List[Dict[str, Any]] = []

    g = record.get("general") or {}
    if g:
        obs.append(_obs(sha, "static.general_file_info", {
            "size": g.get("size"), "virtual_size": g.get("vsize"),
            "has_debug": g.get("has_debug"),
            "exported_functions": g.get("exports"),
            "imported_functions": g.get("imports"),
            "has_relocations": g.get("has_relocations"),
            "has_resources": g.get("has_resources"),
            "has_signature_structure": g.get("has_signature"),
            "has_tls": g.get("has_tls"), "symbols": g.get("symbols"),
        }, limitations=[
            "has_signature_structure = a signature is PRESENT in the PE; it is NOT "
            "verified/validated. No cryptographic trust is established."]))

    h = record.get("header") or {}
    coff = h.get("coff") or {}
    opt = h.get("optional") or {}
    if coff or opt:
        obs.append(_obs(sha, "static.pe_header", {
            "machine": coff.get("machine"),
            "coff_characteristics": coff.get("characteristics"),
            "timestamp": coff.get("timestamp"),
            "subsystem": opt.get("subsystem"), "magic": opt.get("magic"),
            "dll_characteristics": opt.get("dll_characteristics"),
            "major_subsystem_version": opt.get("major_subsystem_version"),
        }, limitations=["timestamp is the declared COFF timestamp; it can be forged."]))

    sec = record.get("section") or {}
    sections = sec.get("sections") or []
    if sections:
        trimmed = [{"name": s.get("name"), "size": s.get("size"),
                    "entropy": round(float(s.get("entropy", 0.0)), 3),
                    "virtual_size": s.get("vsize")}
                   for s in sections[:MAX_SECTIONS]]
        high_entropy = sum(1 for s in sections if float(s.get("entropy", 0)) >= 7.0)
        wx = sum(1 for s in sections
                 if "MEM_WRITE" in (s.get("props") or []) and "MEM_EXECUTE" in (s.get("props") or []))
        obs.append(_obs(sha, "static.sections", {
            "entry_section": sec.get("entry"),
            "section_count": len(sections),
            "sections": trimmed,
            "sections_truncated": len(sections) > MAX_SECTIONS,
            "high_entropy_section_count_ge7": high_entropy,
            "writable_and_executable_section_count": wx,
        }, limitations=[
            "High entropy may indicate packing/compression/encryption but is NOT proof "
            "of maliciousness; benign packers exist."]))

    imp = record.get("imports") or {}
    if imp:
        libs = list(imp.keys())[:MAX_LIBRARIES]
        funcs: List[str] = []
        for lib in imp:
            for fn in imp[lib]:
                funcs.append(f"{lib}:{fn}")
                if len(funcs) >= MAX_IMPORT_FUNCS:
                    break
            if len(funcs) >= MAX_IMPORT_FUNCS:
                break
        total_funcs = sum(len(v) for v in imp.values())
        obs.append(_obs(sha, "static.imports_summary", {
            "library_count": len(imp), "libraries": libs,
            "total_imported_functions": total_funcs,
            "sampled_imports": funcs,
            "imports_truncated": total_funcs > len(funcs),
        }, limitations=[
            "Imports indicate capabilities the binary CAN use statically; they do NOT "
            "prove the behaviour was executed."]))

    exports = record.get("exports") or []
    if exports:
        obs.append(_obs(sha, "static.exports_summary", {
            "export_count": len(exports), "sampled_exports": exports[:30]}))

    st = record.get("strings") or {}
    if st:
        obs.append(_obs(sha, "static.strings_summary", {
            "num_strings": st.get("numstrings"),
            "avg_length": round(float(st.get("avlength", 0.0)), 2),
            "string_entropy": round(float(st.get("entropy", 0.0)), 3),
            "c_drive_path_occurrences": st.get("paths"),
            "url_occurrences": st.get("urls"),
            "registry_key_occurrences": st.get("registry"),
            "embedded_MZ_occurrences": st.get("MZ"),
        }, limitations=[
            "These are COUNTS of printable-string patterns, not observed behaviour. "
            "A URL/registry/MZ count is a static indicator only."]))

    dd = record.get("datadirectories") or []
    if dd:
        names = {"EXPORT_TABLE": 0, "IMPORT_TABLE": 1, "RESOURCE_TABLE": 2,
                 "CERTIFICATE_TABLE": 4, "BASE_RELOCATION_TABLE": 5, "DEBUG": 6,
                 "TLS_TABLE": 9, "IAT": 12}
        present = {name: (dd[i].get("size", 0) > 0) for name, i in names.items() if i < len(dd)}
        obs.append(_obs(sha, "static.data_directories", {
            "present_nonempty": present,
            "has_certificate_table": present.get("CERTIFICATE_TABLE", False),
        }, limitations=[
            "CERTIFICATE_TABLE presence = a signature blob exists; NOT a trust verdict."]))

    return {"target_sha256": sha, "observations": obs}


def prediction_observation(record_sha: str, prediction_payload: Mapping[str, Any]) -> Dict[str, Any]:
    """Wrap the LightGBM static prediction as an evidence observation."""
    o = _obs(record_sha, "static.pe_malware_prediction", dict(prediction_payload),
             limitations=list(prediction_payload.get("limitations", [])))
    return o

evaluation/task05d/grading_import.py:
"""Import + validate + aggregate human annotation exports (multi-reviewer).

Reads reviewer annotation JSON files exported by the offline grading UI, validates
them strictly, aggregates per reviewer, and computes inter-rater agreement when >=2
reviewers scored the same items. Raw scores are preserved; disagreements are flagged
for HUMAN adjudication and never auto-resolved. No scores are generated here and no
LLM is used as a judge. Nothing is reported COMPLETE unless every expected slot is
validly filled.
"""
from __future__ import annotations

import argparse
import json
from collections import defaultdict
from pathlib import Path
from statistics import mean
from typing import Any, Dict, List

from evaluation.task05c.repair.grading_aggregate import CRITERIA, _valid_score


def _validate_file(obj, path) -> List[str]:
    errs = []
    if obj.get("schema_version") != "task05d-annotations-v1":
        errs.append(f"{path.name}: bad schema_version {obj.get('schema_version')!r}")
    if not obj.get("reviewer_id"):
        errs.append(f"{path.name}: missing reviewer_id")
    if not obj.get("rubric_version"):
        errs.append(f"{path.name}: missing rubric_version")
    if not obj.get("exported_at"):
        errs.append(f"{path.name}: missing exported_at timestamp")
    return errs


def load_reviews(paths: List[Path]):
    reviews = []
    errors = []
    seen_reviewers = {}
    for p in paths:
        obj = json.loads(p.read_text(encoding="utf-8"))
        errors += _validate_file(obj, p)
        rid = obj.get("reviewer_id")
        if rid in seen_reviewers:
            errors.append(f"duplicate reviewer_id {rid!r} in {p.name} and {seen_reviewers[rid]}")
        seen_reviewers[rid] = p.name
        # per (sample,label) scores; detect duplicates + invalid scores
        scores = {}
        seen_items = set()
        for a in obj.get("annotations", []):
            key = (a.get("sample_id"), a.get("blind_label"))
            if a.get("blind_label") not in ("X", "Y"):
                errors.append(f"{rid}: bad blind_label {a.get('blind_label')!r} for {a.get('sample_id')}")
            if key in seen_items:
                errors.append(f"{rid}: duplicate annotation for {key}")
            seen_items.add(key)
            sc = a.get("scores") or {}
            clean = {}
            for c in CRITERIA:
                v = sc.get(c)
                if v is None or v == "CHƯA CHẤM":
                    continue
                if not _valid_score(v):
                    errors.append(f"{rid}/{key}/{c}: invalid score {v!r} (only 0/1/2)")
                else:
                    clean[c] = int(v)
            scores[key] = clean
        reviews.append({"reviewer_id": rid, "rubric_version": obj.get("rubric_version"),
                        "exported_at": obj.get("exported_at"), "scores": scores,
                        "source": p.name})
    return reviews, errors


def _cohen_kappa(a: List[int], b: List[int], cats=(0, 1, 2)) -> float:
    n = len(a)
    if n == 0:
        return float("nan")
    po = sum(1 for x, y in zip(a, b) if x == y) / n
    pe = 0.0
    for c in cats:
        pa = sum(1 for x in a if x == c) / n
        pb = sum(1 for x in b if x == c) / n
        pe += pa * pb
    if pe >= 1.0:
        return 1.0 if po >= 1.0 else 0.0
    return (po - pe) / (1 - pe)


def aggregate(reviews, expected_items=None) -> Dict[str, Any]:
    per_reviewer = {}
    for r in reviews:
        filled_items = sum(1 for k, sc in r["scores"].items()
                           if all(c in sc for c in CRITERIA))
        means = {}
        for c in CRITERIA:
            vals = [sc[c] for sc in r["scores"].values() if c in sc]
            means[c] = {"mean": round(mean(vals), 3), "n": len(vals)} if vals else "CHƯA CHẤM"
        missing = None
        if expected_items is not None:
            have = {k for k, sc in r["scores"].items() if all(c in sc for c in CRITERIA)}
            missing = sorted(expected_items - have)
        status = ("COMPLETE" if (expected_items is not None and not missing)
                  else ("PARTIAL" if filled_items > 0 else "CHƯA CHẤM"))
        per_reviewer[r["reviewer_id"]] = {
            "status": status, "filled_items": filled_items,
            "expected_items": len(expected_items) if expected_items is not None else None,
            "missing_items": missing, "per_criterion_mean": means,
            "rubric_version": r["rubric_version"], "exported_at": r["exported_at"]}

    # Inter-rater agreement (pairwise) on commonly-scored items.
    inter = {}
    disagreements = []
    rids = [r["reviewer_id"] for r in reviews]
    by_rid = {r["reviewer_id"]: r["scores"] for r in reviews}
    for i in range(len(rids)):
        for j in range(i + 1, len(rids)):
            ra, rb = rids[i], rids[j]
            common = set(by_rid[ra]) & set(by_rid[rb])
            pair = {}
            for c in CRITERIA:
                a, b, items = [], [], []
                for k in sorted(common):
                    if c in by_rid[ra][k] and c in by_rid[rb][k]:
                        a.append(by_rid[ra][k][c]); b.append(by_rid[rb][k][c]); items.append(k)
                if a:
                    agree = sum(1 for x, y in zip(a, b) if x == y) / len(a)
                    pair[c] = {"n": len(a), "percent_agreement": round(agree, 3),
                               "cohen_kappa": round(_cohen_kappa(a, b), 3)}
                    for k, x, y in zip(items, a, b):
                        if x != y:
                            disagreements.append({"reviewers": [ra, rb], "sample": k[0],
                                                  "blind_label": k[1], "criterion": c,
                                                  "scores": [x, y]})
                else:
                    pair[c] = "insufficient overlap"
            inter[f"{ra}|{rb}"] = pair

    overall = "CHƯA CHẤM"
    statuses = {v["status"] for v in per_reviewer.values()}
    if statuses == {"COMPLETE"} and per_reviewer:
        overall = "COMPLETE"
    elif any(s in ("COMPLETE", "PARTIAL") for s in statuses):
        overall = "PARTIAL"

    return {
        "schema_version": "task05d-grading-aggregate-v1",
        "n_reviewers": len(reviews),
        "overall_status": overall,
        "per_reviewer": per_reviewer,
        "inter_rater_agreement": inter if len(reviews) >= 2 else "N/A (need >=2 reviewers)",
        "disagreements_for_adjudication": disagreements,
        "n_disagreements": len(disagreements),
        "note": "Raw human scores preserved; disagreements are for HUMAN adjudication, not "
                "auto-resolved. No auto-fill, no LLM-as-judge. COMPLETE needs every expected "
                "slot validly filled by the reviewer.",
    }


def main(argv=None):
    ap = argparse.ArgumentParser(description="Import + aggregate human annotations")
    ap.add_argument("--annotations", nargs="+", required=True, help="reviewer export JSON files")
    ap.add_argument("--forms", default=None, help="blind forms (to compute expected item set)")
    ap.add_argument("--out", required=True)
    args = ap.parse_args(argv)

    expected = None
    if args.forms:
        forms = json.loads(Path(args.forms).read_text(encoding="utf-8"))
        expected = set()
        for s in forms["forms"]:
            for f in s["forms"]:
                expected.add((s["sample_id"], f["report_label"]))

    reviews, errors = load_reviews([Path(p) for p in args.annotations])
    if errors:
        rep = {"status": "INVALID", "validation_errors": errors}
    else:
        rep = aggregate(reviews, expected_items=expected)
        rep["validation_errors"] = []
    Path(args.out).parent.mkdir(parents=True, exist_ok=True)
    Path(args.out).write_text(json.dumps(rep, indent=2, ensure_ascii=False), encoding="utf-8")
    print(json.dumps({"n_reviewers": rep.get("n_reviewers", 0),
                      "overall_status": rep.get("overall_status", rep.get("status")),
                      "n_disagreements": rep.get("n_disagreements"),
                      "validation_errors": rep["validation_errors"][:5]},
                     indent=2, ensure_ascii=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

evaluation/task06a/consistency.py:
"""TASK 06A — deterministic decision-consistency checker + fail-safe recommendation.

The Agent supplies the *evidence reasoning* (alignment + which evidence supports /
contradicts the static label + uncertainty). This module is the deterministic
guardrail that (a) checks that reasoning is internally coherent and (b) derives the
final handling recommendation so an unsafe or malformed model suggestion can never
silently become MONITOR.

Documented v1 failures this targets:
  * MONITOR recommended on a malicious-predicted sample (under-cautious),
  * CONFLICT alignment with review_required = false,
  * near-threshold score waved through as MONITOR without review,
  * recommendation / review_required incoherence,
  * `alignment = CONSISTENT` that the supporting/contradicting structure does not
    actually justify (the core "absence-of-disconfirmation" bug).

Score is uncalibrated: proximity is measured in raw-score space only and labelled
as such. The checker never changes the static label and never auto-executes.
"""
from __future__ import annotations

from typing import Any, Dict, List, Mapping, Optional
import math

# Raw-score proximity band around the threshold. The score is NOT a probability;
# this is only "the detector was near its own decision boundary".
NEAR_THRESHOLD_MARGIN = 0.05

_PRIORITY = {"LOW": 0, "MEDIUM": 1, "HIGH": 2}


def is_near_threshold(raw_score: Optional[float], threshold: float,
                      margin: float = NEAR_THRESHOLD_MARGIN) -> bool:
    if raw_score is None:
        return False
    try:
        return math.isfinite(float(raw_score)) and abs(float(raw_score) - float(threshold)) < margin
    except (TypeError, ValueError):
        return False


def safe_recommendation(static_label: str, alignment: Optional[str],
                        near_threshold: bool) -> Dict[str, Any]:
    """Deterministic, fail-safe handling suggestion. Never auto-executes."""
    label = (static_label or "").lower()
    if label == "malicious":
        action, priority = "CONSIDER_QUARANTINE", "HIGH"
    elif label == "benign":
        action, priority = "MONITOR", "LOW"
    else:
        action, priority = "MANUAL_REVIEW", "MEDIUM"

    reasons = [f"base: static label = {label or 'unknown'}"]
    # A reported conflict always escalates to human review.
    if alignment == "CONFLICT":
        action, priority = "MANUAL_REVIEW", "HIGH"
        reasons.append("alignment=CONFLICT -> human review")
    # Near the detector's own boundary: never a quiet MONITOR.
    if near_threshold and action == "MONITOR":
        action, priority = "MANUAL_REVIEW", "MEDIUM"
        reasons.append("near-threshold (raw score) -> escalate MONITOR to MANUAL_REVIEW")
    # Insufficient evidence on a non-benign label should see a human.
    if alignment not in {"CONSISTENT", "CONFLICT"}:
        action, priority = "MANUAL_REVIEW", "MEDIUM"
        reasons.append("insufficient/unknown evidence assessment -> MANUAL_REVIEW")
    return {
        "action": action, "priority": priority,
        "requires_human_decision": True, "execution_status": "NOT_EXECUTED",
        "derivation": reasons,
        "note": "Deterministic fail-safe recommendation; the system never auto-quarantines/kills.",
    }


def check_consistency(assessment: Mapping[str, Any], *, static_label: str,
                      raw_score: Optional[float], threshold: float) -> Dict[str, Any]:
    """Return consistency flags + the deterministic fail-safe recommendation.

    `assessment` may be a v2 assessment (with supporting/contradicting ids) or a
    v1-shaped dict (alignment + recommendation + review_required); missing lists
    are treated as empty so v1 is still gradeable on the shared structural rules.
    """
    alignment = assessment.get("alignment") or assessment.get("evidence_alignment")
    recommendation = assessment.get("recommendation") or assessment.get("agent_recommendation")
    review_required = assessment.get("review_required")
    supporting = list(assessment.get("supporting_evidence_ids", []) or [])
    contradicting = list(assessment.get("contradicting_evidence_ids", []) or [])

    near = is_near_threshold(raw_score, threshold)
    flags: List[str] = []
    try:
        valid_score = (not isinstance(raw_score, bool) and raw_score is not None
                       and math.isfinite(float(raw_score)) and math.isfinite(float(threshold))
                       and 0 <= float(raw_score) <= 1 and 0 <= float(threshold) <= 1)
    except (ValueError, TypeError):
        valid_score = False
    if not valid_score:
        flags.append("invalid_or_missing_score")
    elif static_label not in {"benign", "malicious"} or (float(raw_score) >= float(threshold)) != (static_label == "malicious"):
        flags.append("label_score_threshold_mismatch")
    if alignment not in {"CONSISTENT", "CONFLICT", "INSUFFICIENT_EVIDENCE"}:
        flags.append("invalid_or_missing_alignment")
    if type(review_required) is not bool:
        flags.append("invalid_or_missing_review_flag")

    # --- structural alignment coherence (v2 has the lists; v1 cannot be checked here) ---
    has_structure = ("supporting_evidence_ids" in assessment
                     or "contradicting_evidence_ids" in assessment)
    if has_structure:
        if alignment == "CONSISTENT" and (not supporting or contradicting):
            flags.append("alignment_consistent_not_justified_by_structure")
        if alignment == "CONFLICT" and not contradicting:
            flags.append("alignment_conflict_without_contradicting_evidence")

    # --- recommendation safety vs label ---
    valid_recos = {"MANUAL_REVIEW", "MONITOR", "AVOID_EXECUTION", "CONSIDER_QUARANTINE"}
    if recommendation not in valid_recos:
        flags.append("invalid_or_missing_recommendation")
    else:
        if (static_label or "").lower() == "malicious" and recommendation == "MONITOR":
            flags.append("under_cautious_monitor_on_malicious")
        if alignment == "CONFLICT" and recommendation == "MONITOR":
            flags.append("monitor_despite_conflict")
        if near and recommendation == "MONITOR":
            flags.append("monitor_on_near_threshold")

    # --- review_required coherence ---
    if review_required is False:
        if alignment == "INSUFFICIENT_EVIDENCE":
            flags.append("insufficient_evidence_without_review")
        if alignment == "CONFLICT":
            flags.append("conflict_without_review")
        if (static_label or "").lower() == "malicious":
            flags.append("malicious_without_review")
        if near:
            flags.append("near_threshold_without_review")
    if recommendation == "MANUAL_REVIEW" and review_required is False:
        flags.append("manual_review_recommended_but_review_required_false")

    safe = safe_recommendation(static_label, alignment, near)
    if flags:
        safe.update(action="MANUAL_REVIEW", priority="HIGH")
        safe["derivation"].append("validation flags -> human review; preserve raw suggestion")
    safe["review_required"] = safe["action"] != "MONITOR"
    agent_matches_safe = (recommendation == safe["action"])

    return {
        "near_threshold": near,
        "flags": flags,
        "consistent": not flags,
        "safe_recommendation": safe,
        "agent_recommendation": recommendation,
        "agent_matches_safe_recommendation": agent_matches_safe,
    }

evaluation/task06a/verification.py:
"""Bounded screening against exactly what the model saw, NOT a semantic judge.

No flag means 'not detected by these rules', never 'all claims verified'.
Original records remain separate so projection loss can be audited.
"""
from __future__ import annotations

import json
import re
from .grounding import check_grounding
from .consistency import check_consistency


def visible_projection(facts):
    observations, incomplete = [], []
    for ev in facts["evidence"]:
        value = ev.get("value")
        try:
            value = json.loads(value) if isinstance(value, str) else value
        except ValueError:
            incomplete.append(ev["evidence_id"])
            value = {}
        if ev.get("status") != "SUCCESS" or not isinstance(value, dict):
            incomplete.append(ev["evidence_id"])
            value = {}
        observations.append({**ev, "value": value})
    return {"observations": observations}, sorted(set(incomplete))


def screen(assessment, facts, prediction):
    projection, incomplete = visible_projection(facts)
    ids = {e["evidence_id"] for e in facts["evidence"]}
    pred_ids = {e["evidence_id"] for e in facts["evidence"]
                if e["facet"] == "static.pe_malware_prediction"}
    refs = (assessment.get("evidence_refs", []) + assessment.get("supporting_evidence_ids", [])
            + assessment.get("contradicting_evidence_ids", [])
            + [i for c in assessment.get("claims", []) for i in c["evidence_ids"]])
    text = " ".join(str(assessment.get(k, "")) for k in ("explanation", "rationale"))
    grounding = check_grounding(text, refs, projection)
    # When a whole value was cut, absence from the parsed value cannot disprove a claim.
    # Keep these legacy regex flags as suspects, explicitly unverified.
    claim_flags = []
    for n, claim in enumerate(assessment.get("claims", [])):
        cited = set(claim["evidence_ids"])
        if claim["kind"] == "OBSERVED":
            if not cited:
                claim_flags.append([n, "observed_without_source"])
            if cited & set(incomplete):
                claim_flags.append([n, "source_incomplete_requires_verification"])
            local = {"observations": [e for e in projection["observations"] if e["evidence_id"] in cited]}
            result = check_grounding(claim["text"], claim["evidence_ids"], local)
            if not result["grounded"]:
                claim_flags.append([n, "specific_not_supported_by_cited_visible_source"])
    flags = []
    if set(refs) - ids:
        flags.append("unknown_or_not_visible_evidence_id")
    if (set(assessment.get("supporting_evidence_ids", []))
            | set(assessment.get("contradicting_evidence_ids", []))) & pred_ids:
        flags.append("prediction_used_as_own_corroboration")
    if assessment.get("alignment") == "INSUFFICIENT_EVIDENCE" and assessment.get("confidence_in_assessment") == "HIGH":
        # High certainty of insufficiency can be legitimate; require an explicit limitation.
        if not assessment.get("uncertainty_notes"):
            flags.append("high_confidence_without_limitation")
    if re.search(r"\b(?:\d+(?:\.\d+)?%\s*(?:probability|chance|certain)|calibrated probability of|definitely (?:benign|malicious))", text, re.I):
        flags.append("false_confidence_or_probability_claim_suspected")
    consistency = check_consistency(assessment, static_label=prediction["predicted_label"],
                                    raw_score=prediction["raw_score"], threshold=prediction["threshold"])
    effective = dict(consistency["safe_recommendation"])
    if flags or claim_flags or not grounding["grounded"]:
        effective.update(action="MANUAL_REVIEW", priority="HIGH", review_required=True)
        effective["derivation"] = effective["derivation"] + ["evidence screening requires human verification"]
    return {"citation_count": len(refs), "valid_citation_count": sum(i in ids for i in refs),
            "invalid_ids": sorted(set(refs) - ids), "grounding_screen": grounding,
            "claim_flags": claim_flags, "flags": flags,
            "incomplete_visible_ids": incomplete, "consistency": consistency,
            "effective_recommendation": effective,
            "semantic_grounding": "NOT_ESTABLISHED_RULE_SCREEN_ONLY"}

investigation_v3/application.py:
"""App integration; deterministic detector first, supplemental analyzer only on LLM request."""
import json
from pathlib import Path
import uuid

from agent.config import AgentConfig
from dacn import application as app, investigation as inv
import case_manager as cm
from . import audit, workflow
from .import_adapter import MAX_BYTES


def prepare(config, *, file=None, case_id=None):
    if file is not None:
        try:
            if Path(file).stat().st_size > MAX_BYTES:
                raise app.ApplicationError("Multi-step PE exceeds 8 MiB input budget")
        except OSError as exc:
            raise app.ApplicationError("Target metadata unavailable") from exc
    manifest = inv.load_model_manifest()
    if file is not None:
        intake = app.intake_file(file, config)
        if intake["collection_status"] == "FAILED":
            raise app.ApplicationError("Node B intake failed")
        case_id = intake["case_id"]
    path = cm.case_path(config.cases_dir, case_id)
    state = cm.validate_case(cm.read_json(path))
    registry, orch = inv.build_detector_backend(config, manifest, include_imports=True)
    events = []
    policy = audit.attach(orch, events)
    if inv.read_prediction_evidence(state) is None:
        record = inv.run_static_prediction(config, orch, path, state)
        if record.outcome != "SUCCESS":
            raise app.ApplicationError("Detector did not commit a prediction: " + str(record.reason_code))
    return path, registry, orch, policy, events


def investigate(config, *, file=None, case_id=None, agent_config=None, planner=None, repair=False):
    try:
        path, registry, orch, policy, events = prepare(config, file=file, case_id=case_id)
    except inv.DetectorUnavailableError as exc:
        return {"supported": True, "overall_status": "BLOCKED_DETECTOR", "error": str(exc),
                "report_paths": {}, "report": None}
    cfg = agent_config or AgentConfig(max_iterations=3, max_context_chars=24000)
    if repair:
        from . import repair_workflow
        report = repair_workflow.run(path, cfg, registry, orch, policy, planner=planner, events=events)
    else:
        report = workflow.run(path, cfg, registry, orch, policy, planner=planner, events=events)
    folder = config.home / "reports"
    folder.mkdir(exist_ok=True)
    target = folder / (report["case_id"] + "-" + uuid.uuid4().hex[:8])
    jp, mp = target.with_suffix(".json"), target.with_suffix(".md")
    jp.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    final = report.get("final") or {}
    mp.write_text("# Phiếu điều tra nhiều bước\n\nTrạng thái: " + report["status"]
                  + "\n\nPrediction (raw score không phải xác suất): " + json.dumps(report["model_prediction"], ensure_ascii=False)
                  + "\n\nAssessment và phân biệt bằng chứng cũ/mới:\n\n```json\n" + json.dumps(final, ensure_ascii=False, indent=2)
                  + "\n```\n\nTrusted verification / recommendation (chưa thực thi):\n\n```json\n"
                  + json.dumps(report.get("verification"), ensure_ascii=False, indent=2) + "\n```\n", encoding="utf-8")
    with mp.open("a", encoding="utf-8") as stream:
        if repair:
            stream.write("\nTrusted provenance (metadata only; semantic review pending):\n\n```json\n"
                         + json.dumps(report.get("trusted_metadata"), ensure_ascii=False, indent=2) + "\n```\n")
            if report.get("final") is None:
                stream.write("\nINVESTIGATION_INCOMPLETE / MANUAL_REVIEW: no accepted Agent final.\n")
        stream.write("\nEffective recommendation (trusted, không containment):\n\n```json\n"
                     + json.dumps(report["effective_recommendation"], ensure_ascii=False, indent=2) + "\n```\n")
    return {"supported": True, "overall_status": "COMPLETED" if report["status"] == "FINISHED" else report["status"],
            "case_id": report["case_id"], "report_paths": {"json": str(jp), "markdown": str(mp)}, "report": report}

investigation_v3/audit.py:
"""Observe actual trusted stages, without changing decisions or logging key material."""
import copy


def attach(orch, events):
    policy, bridge = orch._policy, orch._bridge
    class Policy:
        def evaluate(self, *args):
            decision = policy.evaluate(*args)
            events.append({"stage": "D4", "decision": copy.deepcopy(decision)})
            return decision
    class Bridge:
        def __getattr__(self, name):
            return getattr(bridge, name)
        def commit_tool_result(self, case_path, result, receipt, **kwargs):
            try:
                committed = bridge.commit_tool_result(case_path, result, receipt, **kwargs)
            except Exception as exc:
                events.append({"stage": "D9_FAILED", "error_type": type(exc).__name__})
                raise
            events.append({"stage": "D9_COMMITTED", "commit": copy.deepcopy(committed)})
            return committed
    orch._policy, orch._bridge = Policy(), Bridge()
    for tool_id, normalizer in list(orch._result_adapters.items()):
        def wrapped(output, call, spec, *, artifact_root, _normalizer=normalizer):
            events.append({"stage": "D5_D6_RECEIPT", "receipt": copy.deepcopy(output.receipt),
                           "exit_code": output.exit_code})
            result = _normalizer(output, call, spec, artifact_root=artifact_root)
            events.append({"stage": "D7_VALIDATED", "result": copy.deepcopy(result)})
            return result
        orch._result_adapters[tool_id] = wrapped
    return policy  # discovery uses pure policy, without recording it as authorization

investigation_v3/grounding.py:
"""Literal new-fact checks; semantic relevance remains unverified."""
import copy
from evaluation.task06a.verification import screen
from .imports_tool import FACET


def verify(proposal, facts, initial_ids, prediction):
    visible = {e["evidence_id"]: e for e in facts["evidence"]}
    checks_facts = copy.deepcopy(facts)
    for e in checks_facts["evidence"]:
        if e["facet"] == FACET and isinstance(e["value"], dict):
            entries = e["value"]["entries"]
            e["facet"] = "static.imports_summary"
            e["value"] = {"libraries": sorted({x["library"] for x in entries}),
                          "sampled_imports": [x["library"] + ":" + (x["symbol"] or "ordinal" + str(x["ordinal"])) for x in entries]}
    checks = screen(proposal["assessment"], checks_facts, prediction)
    uses, invalid = [], []
    for use in proposal["new_fact_uses"]:
        ev = visible.get(use["evidence_id"], {})
        valid = (use["evidence_id"] not in initial_ids and ev.get("facet") == FACET
                 and any(x["library"] == use["library"] and x["symbol"] == use["symbol"]
                         for x in (ev.get("value") or {}).get("entries", [])))
        (uses if valid else invalid).append(use)
    if invalid:
        checks["effective_recommendation"].update(action="MANUAL_REVIEW", review_required=True)
    checks.update(literal_new_fact_uses=uses, unsupported_new_fact_uses_suspected=invalid,
                  semantic_relevance="PENDING_INDEPENDENT_REVIEW")
    return checks

investigation_v3/import_adapter.py:
"""Pinned standalone read-only PE imports analyzer. No shell/network/target execution."""
import argparse
import hashlib
import json
from pathlib import Path
import sys

MAX_BYTES = 8 * 1024 * 1024
MAX_ENTRIES = 64


def inspect_bytes(data):
    if len(data) > MAX_BYTES:
        raise ValueError("PE exceeds 8 MiB analyzer budget")
    if len(data) < 64 or data[:2] != b"MZ":
        raise ValueError("Invalid PE")
    import lief
    binary = lief.PE.parse(list(data))
    if binary is None:
        raise ValueError("PE parser returned no binary")
    entries, libraries, total = [], set(), 0
    # Preserve declaration order; bounded output is deterministic, not risk-ranked.
    for delay, table in ((False, binary.imports), (True, binary.delay_imports)):
        for lib in table:
            name = lib.name
            if not name or len(name) > 128:
                raise ValueError("Import library exceeds name budget")
            libraries.add(name)
            for item in lib.entries:
                ordinal = int(item.ordinal) if item.is_ordinal else None
                symbol = None if item.is_ordinal else item.name
                if symbol is not None and (not symbol or len(symbol) > 160):
                    raise ValueError("Import symbol exceeds name budget")
                total += 1
                if total <= MAX_ENTRIES:
                    entries.append({"library": name, "symbol": symbol, "ordinal": ordinal, "delay": delay})
                if total > 100000 or len(libraries) > 4096:
                    raise ValueError("Import table resource budget exceeded")
    return {"schema_version": "pe-imports-output-v1", "target_sha256": hashlib.sha256(data).hexdigest(),
            "parser": "LIEF " + lief.__version__, "library_count": len(libraries),
            "total_entries": total, "returned_entries": len(entries),
            "truncated": total > MAX_ENTRIES, "entries": entries,
            "limitations": ["Declared static imports only; does not prove runtime use or maliciousness.",
                            "Dynamically resolved APIs are not enumerated.",
                            "First 64 declarations in file order; absence from truncated output is unknown."]}


def inspect_file(path):
    with open(path, "rb") as stream:
        data = stream.read(MAX_BYTES + 1)
    return inspect_bytes(data)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--target", required=True)
    ap.add_argument("--arguments-json", required=True)
    args = ap.parse_args()
    try:
        if json.loads(args.arguments_json) != {"max_entries": MAX_ENTRIES}:
            raise ValueError("Invalid imports arguments")
        payload = inspect_file(args.target)
        sys.stdout.write(json.dumps(payload, ensure_ascii=True, allow_nan=False))
    except Exception as exc:
        sys.stderr.write("imports_adapter: " + type(exc).__name__ + ": " + str(exc)[:200])
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

investigation_v3/repair_finalization.py:
"""Validation never edits LLM semantics. Phase enrichment is trusted metadata only."""
import copy
import re
from .grounding import verify
from .imports_tool import FACET


def validate_refs(obj, facts):
    visible = {e['evidence_id']: e for e in facts['evidence']}
    refs = list(obj['evidence_refs'])
    if 'assessment' in obj:
        a = obj['assessment']
        refs += a['supporting_evidence_ids'] + a['contradicting_evidence_ids']
        refs += [i for c in a['claims'] for i in c['evidence_ids']]
        refs += [b['evidence_id'] for b in obj['import_bindings']]
    if set(refs) - visible.keys():
        raise ValueError('EVIDENCE_NOT_VISIBLE: cited ID not present in this prompt')
    return visible, set(refs)


def finalize(obj, facts, initial_ids, prediction):
    visible, refs = validate_refs(obj, facts)
    claims = obj['assessment']['claims']
    uses, bindings = [], []
    for b in obj['import_bindings']:
        if b['claim_index'] >= len(claims):
            raise ValueError('CLAIM_INDEX_UNKNOWN')
        claim = claims[b['claim_index']]
        ev = visible[b['evidence_id']]
        entry = next((e for e in (ev.get('value') or {}).get('entries', [])
                      if e.get('entry_index') == b['entry_index']), None)
        if ev['facet'] != FACET or entry is None or b['evidence_id'] not in claim['evidence_ids']:
            raise ValueError('CLAIM_SOURCE_BINDING: no matching visible entry/source')
        literal = entry['symbol'] if entry['symbol'] is not None else '#' + str(entry['ordinal'])
        if entry['library'] not in claim['text'] or literal not in claim['text']:
            raise ValueError('CLAIM_LITERAL_MISMATCH: selected entry is not stated in claim')
        bindings.append({**copy.deepcopy(b), 'literal': copy.deepcopy(entry),
                         'phase': ev['phase'], 'value_sha256': ev['full_detail_ref']['value_sha256']})
        if b['evidence_id'] not in initial_ids and entry['symbol'] is not None:
            uses.append({'evidence_id': b['evidence_id'], 'library': entry['library'],
                         'symbol': entry['symbol'], 'why_relevant': claim['text']})
    for i, c in enumerate(claims):
        imported = [visible[e] for e in c['evidence_ids'] if visible[e]['facet'] == FACET]
        if c['kind'] == 'OBSERVED' and re.search(r'\.dll\b|\bnull\b', c['text'], re.I):
            if not imported or not any(b['claim_index'] == i for b in bindings):
                raise ValueError('IMPORT_CLAIM_REQUIRES_LITERAL_BINDING')
        if c['kind'] == 'OBSERVED' and not c['evidence_ids']:
            raise ValueError('OBSERVED_WITHOUT_SOURCE')
    checks = verify({'assessment': obj['assessment'], 'new_fact_uses': uses}, facts, initial_ids, prediction)
    text = ' '.join([obj['assessment']['explanation']] + [c['text'] for c in claims])
    if (not any(e['facet'] == FACET and e['status'] == 'SUCCESS' for e in visible.values())
            and re.search(r'no (?:declared )?imports (?:are )?declared|no declared imports|no imports exist', text, re.I)):
        checks['flags'].append('absence_claim_without_imports_source_suspected_unverified')
    if any(re.search(r'\bentropy\b|\b\d+(?:\.\d+)?\s*%\s*(?:probability|chance)', c['text'], re.I)
           for c in claims):
        checks['flags'].append('numeric_or_entropy_claim_suspected_unverified')
    flagged = bool(checks['flags'] or checks['claim_flags'] or checks['consistency']['flags']
                   or not checks['grounding_screen']['grounded'])
    if flagged:
        checks['effective_recommendation'].update(action='MANUAL_REVIEW', review_required=True,
                                                 requires_human_decision=True)
    return {'llm_assessment': copy.deepcopy(obj),
            'trusted_metadata': {'case_id': facts['case_id'], 'case_revision': facts['case_revision'],
                'target_sha256': facts['target_sha256'], 'cited_initial_ids': sorted(refs & initial_ids),
                'cited_committed_during_run_ids': sorted(refs - initial_ids),
                'claim_literal_bindings': bindings, 'semantic_grounding': 'PENDING_INDEPENDENT_REVIEW'},
            'verification': checks, 'has_suspected_or_consistency_flags': flagged}

